import sys

def encode(arr, length):
    val = 0
    for i in range(length):
        val = val * 3 + arr[i]
    return val

def decode(arr, length, code, base):
    for j in range(length - 1, -1, -1):
        arr[j] = code % base
        code //= base

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    if n < m:
        n, m = m, n
    totalStates = 1
    for _ in range(m):
        totalStates *= 3
    dp = [-1] * totalStates
    nextDp = [-1] * totalStates
    stateA = [1] * m
    stateB = [0] * m
    dp[encode(stateA, m)] = 0
    for _ in range(n):
        for i in range(totalStates):
            nextDp[i] = -1
        for stateIdx in range(totalStates):
            if dp[stateIdx] < 0:
                continue
            decode(stateA, m, stateIdx, 3)
            for mask in range(1 << m):
                decode(stateB, m, mask, 2)
                invalid = False
                for j in range(m):
                    if stateA[j] == 0 and stateB[j] == 0:
                        invalid = True
                        break
                if invalid:
                    continue
                countOnes = 0
                for j in range(m):
                    if stateB[j] == 1:
                        stateB[j] = 2
                        countOnes += 1
                for j in range(m):
                    if stateB[j] == 0 and (stateA[j] == 2 or (j > 0 and stateB[j - 1] == 2) or (j + 1 < m and stateB[j + 1] == 2)):
                        stateB[j] = 1
                newStateIdx = encode(stateB, m)
                if nextDp[newStateIdx] < dp[stateIdx] + m - countOnes:
                    nextDp[newStateIdx] = dp[stateIdx] + m - countOnes
        dp, nextDp = nextDp, dp
    maxResult = 0
    for idx in range(totalStates):
        if dp[idx] <= maxResult:
            continue
        decode(stateA, m, idx, 3)
        invalid = False
        for j in range(m):
            if stateA[j] == 0:
                invalid = True
                break
        if not invalid:
            maxResult = dp[idx]
    print(maxResult)

if __name__ == "__main__":
    main()

